   if isinstance(n,(ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)) and any(s in n.name.lower() for s in terms): rows.append(f'{n.name}:{n.lineno}-{n.end_lineno}')
  if rows: print(str(p),'; '.join(rows))
